import java.util.*;

class Animal { void eat() { System.out.println("Animal Eating"); } }
class Dog extends Animal { @Override void eat() { System.out.println("Dog Eating"); } }
class Labrador extends Dog { }
class Cat extends Animal { }

public class Main {
    public static void main(String[] args) {
        List<Animal> animals = new ArrayList<>();
        animals.add(new Animal());
        fun(animals);
    }

    static void fun(List<? super Animal> values) {
        values.add(new Dog());
        values.add(new Cat());
        values.add(new Labrador());
        for (Object obj : values) {
            Animal a = (Animal) obj;
            a.eat();
        }
    }
}
